//! Increment 1: election decision segments only. This is NOT yet an adapter for
//! every asynchronous Raft execution. See PROGRESS.md for the open coverage.
#[path = "../src/raft/election.rs"]
pub mod election;
#[path = "segments.rs"]
mod segments;
#[path = "../src/raft/log.rs"]
pub mod log_core;
pub use segments::{State, Input, Output, Message, initial, step, receive, emit};
use crate::support::*;
use vstd::prelude::*;
verus! {
pub type RuntimeState = log_core::Core;
pub open spec fn runtime_initial(s: RuntimeState) -> bool { initial(view(s)) }
pub open spec fn runtime_step(s: RuntimeState,i: Input,t: RuntimeState,o: Output) -> bool { step(view(s),i,view(t),o) }
pub open spec fn view(s: RuntimeState) -> State { State {election:s.election, log:s.log@, commit:s.commit,applied:s.applied} }
// No global Raft invariant is claimed for this partial decision adapter.
pub open spec fn runtime_invariant(s: RuntimeState, sent: Seq<Envelope<Message>>) -> bool { s.election.term <= u64::MAX }
pub proof fn prove_runtime_initial(s: RuntimeState)
    requires runtime_initial(s),
    ensures runtime_invariant(s,Seq::empty()), initial(view(s)),
{}
pub proof fn prove_runtime_step(s: RuntimeState,i: Input,t: RuntimeState,o: Output,
    a: Seq<Envelope<Message>>,b: Seq<Envelope<Message>>)
    requires runtime_invariant(s,a), runtime_step(s,i,t,o), exchange(a,receive(i),emit(o),b),
    ensures runtime_invariant(t,b), step(view(s),i,view(t),o),
{}
pub fn actual_initial() -> (c: RuntimeState)
    ensures runtime_initial(c),
{ log_core::new_core() }
pub fn actual_proposal(c: &mut RuntimeState,entry: log_core::Entry) -> (ok: bool)
    requires old(c).election.role == election::Role::Leader,
    ensures ok ==> runtime_step(*old(c),Input::Propose {entry},*c,Seq::empty()),
        !ok ==> c.log@ == old(c).log@,
{
    log_core::propose(&mut c.log,entry)
}
pub fn actual_insert(c: &mut RuntimeState,at: usize,entry: log_core::Entry) -> (ok: bool)
    requires !(old(c).election.role == election::Role::Leader),
    ensures runtime_step(*old(c),Input::Insert {at:at as nat,entry},*c,Seq::empty()),
{
    log_core::insert(&mut c.log,at,entry)
}

}
//! Partial histories of election decision segments, not complete host executions.
use super::election::*;
use crate::support::*;
use super::log_core::{Entry,inserted};
use vstd::prelude::*;
verus! {
pub enum Message { Request(Vote), Response(Reply), Heartbeat(u64), HeartbeatReply(u64) }
pub enum Input {
    Propose { entry: Entry },
    Insert { at: nat, entry: Entry },
    Commit { index: u64, entry_term: u64, term: u64, replicated: usize, members: usize },
    Apply,
    Timeout { node: u64 },
    SendHeartbeat { group: nat, node: nat, peer: nat },
    HeartbeatDelivery { delivery: Delivery<Message> },
    VoteReplyDelivery { delivery: Delivery<Message>, started: u64, votes: usize, members: usize },
    SendVote { group: nat, node: u64, peer: nat, last_term: u64, last_index: u64 },
    Deliver { delivery: Delivery<Message>, last_term: u64, last_index: u64 },
}
pub type Output = Seq<Envelope<Message>>;
pub open spec fn receive(i: Input) -> Option<Delivery<Message>> {
    match i {
        Input::Deliver { delivery, .. } | Input::HeartbeatDelivery { delivery }
        | Input::VoteReplyDelivery { delivery, .. } => Some(delivery), _ => None }
}
pub open spec fn emit(o: Output) -> Seq<Envelope<Message>> { o }
pub struct State { pub election: Election, pub log: Seq<Entry>, pub commit: u64, pub applied: u64 }
pub open spec fn initial(s: State) -> bool {
    s.election == fresh() && s.log.len() == 0 && s.commit == 0 && s.applied == 0
}
pub open spec fn step(s: State,i: Input,t: State,o: Output) -> bool {
    match i {
        Input::Propose {entry} => s.election.role is Leader && s.log.len() < usize::MAX
            && t == (State { log:s.log.push(entry), ..s }) && o.len() == 0,
        Input::Insert {at,entry} => !(s.election.role is Leader)
            && t == (State { log:inserted(s.log,at,entry), ..s }) && o.len() == 0,
        Input::Commit {index,entry_term,term,replicated,members} =>
            t == (State {commit: if index > s.commit && entry_term == term && replicated > members/2 {index} else {s.commit}, ..s}) && o.len() == 0,
        Input::Apply => s.applied < s.commit && s.commit <= s.log.len()
            && t == (State {applied:(s.applied+1) as u64, ..s}) && o.len() == 0,
        _ => election_step(s.election,i,t.election,o) && t.log == s.log && t.commit == s.commit && t.applied == s.applied,
    }
}
pub open spec fn election_step(s: Election, i: Input, t: Election, o: Output) -> bool {
    match i {
        Input::Propose {..} | Input::Insert {..} | Input::Commit {..} | Input::Apply => false,
        Input::SendHeartbeat { group,node,peer } => t == s && o == seq![Envelope {
            group, sender: node, recipient: peer, body: Message::Heartbeat(s.term) }],
        Input::HeartbeatDelivery { delivery: d } => match d.message.body {
            Message::Heartbeat(term) => t == heartbeat_result(s,term) && o == seq![Envelope {
                group: d.message.group, sender: d.message.recipient, recipient: d.message.sender,
                body: Message::HeartbeatReply(t.term) }],
            Message::HeartbeatReply(term) => t == advanced(s,term) && o == Seq::<Envelope<Message>>::empty(),
            _ => false,
        },
        Input::VoteReplyDelivery { delivery: d, started,votes,members } => match d.message.body {
            Message::Response(r) => t == reply_result(s,r.term,started,r.granted,votes,members)
                && o == Seq::<Envelope<Message>>::empty(),
            _ => false,
        },
        Input::Timeout { node } => t == timeout_result(s,node) && o == Seq::<Envelope<Message>>::empty(),
        Input::SendVote { group, node, peer, last_term, last_index } =>
            t == s && o == seq![Envelope { group, sender: node as nat, recipient: peer,
                body: Message::Request(Vote { term: s.term, candidate: node, last_term, last_index }) }],
        Input::Deliver { delivery: d, last_term, last_index } => match d.message.body {
            Message::Request(v) => t == vote_result(s,v,last_term,last_index)
                && o == seq![Envelope { group: d.message.group, sender: d.message.recipient,
                    recipient: d.message.sender, body: Message::Response(Reply {
                        term: t.term, granted: grant(s,v,last_term,last_index) }) }],
            _ => false, // Different RPC segments use their corresponding input variant.
        },
    }
}
// A concrete send is eligible for receipt, and the real handler produces the
// response specified by the modeled step. No vote correctness is assumed by exchange.
pub fn actual_request_path(sender: Election, receiver: Election, group: Ghost<nat>,
    node: u64, peer: Ghost<nat>, last_term: u64, last_index: u64)
    -> (r: (Election, Reply))
    ensures election_step(receiver, Input::Deliver { delivery: Delivery { send: 0,
        message: Envelope { group: group@, sender: node as nat, recipient: peer@,
        body: Message::Request(Vote { term: sender.term, candidate: node, last_term, last_index }) } },
        last_term, last_index }, r.0,
        seq![Envelope { group: group@, sender: peer@, recipient: node as nat, body: Message::Response(r.1) }]),
{
    let vote = make_vote(sender,node,last_term,last_index);
    let r = request_vote(receiver,vote,last_term,last_index);
    proof {
        let request = Envelope { group: group@, sender: node as nat, recipient: peer@, body: Message::Request(vote) };
        let sent = seq![request];
        let reply = Envelope { group: group@, sender: peer@, recipient: node as nat, body: Message::Response(r.1) };
        assert(exchange(Seq::empty(), None, sent, sent));
        assert(exchange(sent, Some(Delivery { send: 0, message: request }), seq![reply], sent + seq![reply]));
    }
    r
}
pub proof fn segment_vote_stable(s: Election,i: Input,t: Election,o: Output)
    requires election_step(s,i,t,o),
    ensures t.term >= s.term,
        t.term == s.term && s.voted_for.is_some() ==> t.voted_for == s.voted_for,
{
    match i {
        Input::Propose {..} | Input::Insert {..} | Input::Commit {..} | Input::Apply => {},
        Input::Timeout { .. } => {},
        Input::SendVote { .. } => {},
        Input::SendHeartbeat { .. } => {},
        Input::HeartbeatDelivery { delivery } => { match delivery.message.body { _ => {} } },
        Input::VoteReplyDelivery { delivery, .. } => { match delivery.message.body { _ => {} } },
        Input::Deliver { delivery, .. } => { match delivery.message.body { _ => {} } },
    }
}

// Local dependency for leader_append_only. The cluster observation and every
// async caller's coverage must still be established before using the target.
pub proof fn local_leader_append_only(s: State,i: Input,t: State,o: Output)
    requires step(s,i,t,o), s.election.role is Leader,
        t.election.role is Leader, s.election.term == t.election.term,
    ensures s.log.len() <= t.log.len(), t.log.take(s.log.len() as int) == s.log,
{
    match i {
        Input::Propose {entry} => {
            assert(s.log.push(entry).take(s.log.len() as int) =~= s.log);
        },
        _ => {},
    }
}

}
//! Executable log mutations shared with the formal development.
use vstd::prelude::*;
use super::election::*;
verus! {
pub struct Core { pub election: Election, pub log: Vec<Entry>, pub commit: u64, pub applied: u64 }
pub fn new_core() -> (c: Core)
    ensures c.election == fresh(), c.log.len() == 0, c.commit == 0, c.applied == 0,
{ Core { election: new(), log: Vec::new(), commit: 0, applied: 0 } }
#[derive(Clone, Debug)]
#[cfg_attr(not(verus_keep_ghost), derive(serde::Serialize, serde::Deserialize))]
pub struct Entry { pub term: u64, pub command: Vec<u8> }

pub fn matches(log: &Vec<Entry>, prev: usize, term: u64) -> (ok: bool)
    ensures ok == (prev == 0 || (0 < prev <= log.len() && log@[prev as int - 1].term == term)),
{
    prev == 0 || (prev <= log.len() && log[prev - 1].term == term)
}
// A matching term is kept. Equality of its command is a GLOBAL provenance
// obligation, not a precondition used to hide arbitrary received messages.
pub fn insert(log: &mut Vec<Entry>, at: usize, entry: Entry) -> (ok: bool)
    ensures
        ok == (at <= old(log).len() && at < usize::MAX),
        !ok ==> log@ == old(log)@,
        ok && at < old(log).len() && old(log)@[at as int].term == entry.term ==> log@ == old(log)@,
        ok && (at == old(log).len() || old(log)@[at as int].term != entry.term) ==>
            log@ == old(log)@.take(at as int).push(entry),
{
    if at > log.len() || at == usize::MAX { return false; }
    if at < log.len() {
        if log[at].term == entry.term { return true; }
        log.truncate(at);
    }
    log.push(entry);
    true
}
pub fn propose(log: &mut Vec<Entry>, entry: Entry) -> (ok: bool)
    ensures ok == (old(log).len() < usize::MAX),
        ok ==> log@ == old(log)@.push(entry), !ok ==> log@ == old(log)@,
{
    if log.len() == usize::MAX { return false; }
    log.push(entry); true
}
pub fn commit_candidate(current: u64, index: u64, entry_term: u64, term: u64,
    replicated: usize, members: usize) -> (next: u64)
    ensures next == (if index > current && entry_term == term && replicated > members / 2 { index } else { current }),
        next >= current,
{
    if index > current && entry_term == term && replicated > members / 2 { index } else { current }
}
pub open spec fn inserted(log: Seq<Entry>, at: nat, entry: Entry) -> Seq<Entry> {
    if at > log.len() || at >= usize::MAX { log }
    else if at < log.len() && log[at as int].term == entry.term { log }
    else { log.take(at as int).push(entry) }
}
pub fn next_application(applied: u64, committed: u64, len: usize) -> (index: Option<u64>)
    ensures index == (if applied < committed && committed <= len {
        Some((applied + 1) as u64) } else { None }),
        index.is_some() ==> 1 <= index.unwrap() <= len,
{
    if applied < committed && committed <= len as u64 { Some(applied+1) } else { None }
}
pub proof fn insertion_keeps_prefix(log: Seq<Entry>,at: nat,entry: Entry,k: nat)
    requires k <= at <= log.len(), at < usize::MAX,
    ensures inserted(log,at,entry).take(k as int) == log.take(k as int),
{
    if !(at < log.len() && log[at as int].term == entry.term) {
        assert(log.take(at as int).push(entry).take(k as int) =~= log.take(k as int));
    }
}

}
//! DRAFT independent behavioral targets. This is an observation vocabulary,
//! not a prescribed executable representation or a second protocol engine.
use vstd::prelude::*;

verus! {
pub type Group = nat;
pub type Node = nat;
pub type Term = nat;
pub type Index = nat;

pub struct Key { pub group: Group, pub node: Node }
pub struct Entry { pub term: Term, pub command: Seq<u8> }
pub struct Snapshot {
    pub through: Index,
    pub last_term: Term,
    pub bytes: Seq<u8>,
}
pub struct View {
    pub term: Term,
    pub leader: bool,
    // The logical prefix includes compacted entries. It is NOT a free witness:
    // the generated refinement must connect it to actual execution and storage.
    pub log: Seq<Entry>,
    pub snapshot: Option<Snapshot>,
}
pub enum Event {
    Silent,
    Elect { who: Key, term: Term },
    // Observe actual commit-index advancement, never future preservation.
    Commit { who: Key, term: Term, through: Index },
    Apply { who: Key, index: Index, entry: Entry },
    // Logical application of the prefix represented by an installed snapshot.
    ApplySnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    CreateSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    PersistSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    RestoreSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
}
pub struct History {
    // before/after each linearized action, including crash and restart.
    pub states: Seq<Map<Key, View>>,
    pub events: Seq<Event>,
}

pub open spec fn prefix(a: Seq<Entry>, b: Seq<Entry>) -> bool {
    a.len() <= b.len() && a == b.take(a.len() as int)
}
pub open spec fn at(log: Seq<Entry>, index: Index) -> Entry
    recommends 1 <= index <= log.len(),
{ log[index as int - 1] }

pub open spec fn shape(h: History) -> bool {
    h.states.len() == h.events.len() + 1
    && forall |t: int| 0 <= t < h.events.len() ==> match #[trigger] h.events[t] {
        Event::Elect { who, term } =>
            h.states[t + 1].contains_key(who)
            && h.states[t + 1][who].leader
            && h.states[t + 1][who].term == term,
        Event::Commit { who, term, through } =>
            h.states[t + 1].contains_key(who)
            && h.states[t + 1][who].term == term
            && 1 <= through <= h.states[t + 1][who].log.len(),
        Event::Apply { who: _, index, entry: _ } => index >= 1,
        _ => true,
    }
}

pub open spec fn election_safety(h: History) -> bool {
    forall |i: int, j: int| #![trigger h.events[i], h.events[j]] 0 <= i < h.events.len() && 0 <= j < h.events.len() ==>
        match (h.events[i], h.events[j]) {
            (Event::Elect { who: a, term: ta }, Event::Elect { who: b, term: tb }) =>
                a.group == b.group && ta == tb ==> a.node == b.node,
            _ => true,
        }
}

pub open spec fn leader_append_only(h: History) -> bool {
    forall |t: int, k: Key| #![trigger h.states[t][k]] 0 <= t < h.events.len()
        && h.states[t].contains_key(k) && h.states[t + 1].contains_key(k)
        && h.states[t][k].leader && h.states[t + 1][k].leader
        && h.states[t][k].term == h.states[t + 1][k].term
        ==> prefix(h.states[t][k].log, h.states[t + 1][k].log)
}

pub open spec fn log_matching(h: History) -> bool {
    // Compare represented logs across time as well as between nodes.
    forall |s: int, t: int, a: Key, b: Key, index: Index|
        #![trigger at(h.states[s][a].log, index), at(h.states[t][b].log, index)]
        0 <= s < h.states.len() && 0 <= t < h.states.len()
        && a.group == b.group && h.states[s].contains_key(a) && h.states[t].contains_key(b)
        && 1 <= index <= h.states[s][a].log.len() && index <= h.states[t][b].log.len()
        && at(h.states[s][a].log, index).term == at(h.states[t][b].log, index).term
        ==> h.states[s][a].log.take(index as int) == h.states[t][b].log.take(index as int)
}

pub open spec fn leader_completeness(h: History) -> bool {
    forall |c: int, e: int| #![trigger h.events[c], h.events[e]] 0 <= c < h.events.len() && 0 <= e < h.events.len() ==>
        match (h.events[c], h.events[e]) {
            (Event::Commit { who: a, term: tc, through }, Event::Elect { who: b, term: te }) =>
                a.group == b.group && tc < te ==>
                    h.states[e + 1].contains_key(b)
                    && through <= h.states[e + 1][b].log.len()
                    && h.states[c + 1][a].log.take(through as int)
                        == h.states[e + 1][b].log.take(through as int),
            _ => true,
        }
}

pub open spec fn applied(event: Event, group: Group, index: Index) -> Option<Entry> {
    match event {
        Event::Apply { who, index: i, entry } =>
            if who.group == group && i == index { Some(entry) } else { None },
        Event::ApplySnapshot { who, prefix, snapshot: _ } =>
            if who.group == group && 1 <= index <= prefix.len() {
                Some(at(prefix, index))
            } else { None },
        _ => None,
    }
}

pub open spec fn state_machine_safety(h: History) -> bool {
    forall |a: int, b: int, group: Group, index: Index|
        0 <= a < h.events.len() && 0 <= b < h.events.len()
        && applied(h.events[a], group, index).is_some()
        && applied(h.events[b], group, index).is_some()
        ==> applied(h.events[a], group, index) == applied(h.events[b], group, index)
}

// The application semantics is selected per group and refined to the actual
// service. Decoding recovers application state, not historical commands.
pub struct Application {
    pub initial: Seq<u8>,
    pub step: spec_fn(Seq<u8>, Entry) -> Seq<u8>,
    pub decode: spec_fn(Seq<u8>) -> Option<Seq<u8>>,
}
pub open spec fn fold(app: Application, entries: Seq<Entry>) -> Seq<u8>
    decreases entries.len(),
{
    if entries.len() == 0 { app.initial }
    else { (app.step)(fold(app, entries.drop_last()), entries.last()) }
}
pub open spec fn snapshot_represents(app: Application, snap: Snapshot, entries: Seq<Entry>) -> bool {
    snap.through == entries.len()
    && snap.last_term == (if entries.len() == 0 { 0nat } else { entries.last().term })
    && (app.decode)(snap.bytes) == Some(fold(app, entries))
}
pub open spec fn committed_prefix_before(h: History, time: int, group: Group, entries: Seq<Entry>) -> bool {
    entries.len() == 0 || exists |c: int| #![trigger h.events[c]] 0 <= c < time && match h.events[c] {
        Event::Commit { who, term: _, through } => who.group == group
            && entries.len() <= through && h.states[c + 1].contains_key(who)
            && prefix(entries, h.states[c + 1][who].log),
        _ => false,
    }
}
pub open spec fn snapshot_fidelity(h: History, apps: Map<Group, Application>) -> bool {
    (forall |t: int, k: Key| #![trigger h.states[t][k]] 0 <= t < h.states.len() && h.states[t].contains_key(k) ==>
        match h.states[t][k].snapshot {
            None => true,
            Some(s) => apps.contains_key(k.group) && s.through <= h.states[t][k].log.len()
                && snapshot_represents(apps[k.group], s, h.states[t][k].log.take(s.through as int))
                && committed_prefix_before(h, t, k.group, h.states[t][k].log.take(s.through as int)),
        })
    && (forall |t: int| 0 <= t < h.events.len() ==> match #[trigger] h.events[t] {
        Event::ApplySnapshot { who, prefix, snapshot }
        | Event::CreateSnapshot { who, prefix, snapshot }
        | Event::PersistSnapshot { who, prefix, snapshot }
        | Event::RestoreSnapshot { who, prefix, snapshot } =>
            apps.contains_key(who.group) && snapshot_represents(apps[who.group], snapshot, prefix)
                && committed_prefix_before(h, t, who.group, prefix),
        _ => true,
    })
}
} // verus!
//! Shared executable election decisions. Host code supplies log boundaries.
use vstd::prelude::*;
verus! {
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Role { Follower, Candidate, Leader }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Election { pub term: u64, pub role: Role, pub voted_for: Option<u64> }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Vote { pub term: u64, pub candidate: u64, pub last_term: u64, pub last_index: u64 }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Reply { pub term: u64, pub granted: bool }

pub open spec fn fresh() -> Election {
    Election { term: 0, role: Role::Follower, voted_for: None }
}
pub fn new() -> (s: Election) ensures s == fresh() {
    Election { term: 0, role: Role::Follower, voted_for: None }
}
pub open spec fn advanced(s: Election, term: u64) -> Election {
    if term > s.term { Election { term, role: Role::Follower, voted_for: None } } else { s }
}
pub fn advance(s: Election, term: u64) -> (t: Election)
    ensures t == advanced(s, term), t.term >= s.term,
{
    if term > s.term { Election { term, role: Role::Follower, voted_for: None } } else { s }
}
pub open spec fn timeout_result(s: Election, me: u64) -> Election {
    if s.term < u64::MAX { Election { term: (s.term + 1) as u64, role: Role::Candidate, voted_for: Some(me) } }
    else { s }
}
pub fn timeout(s: Election, me: u64) -> (t: Election)
    ensures t == timeout_result(s, me), t.term >= s.term,
{
    if s.term < u64::MAX { Election { term: s.term + 1, role: Role::Candidate, voted_for: Some(me) } } else { s }
}
pub open spec fn grant(s: Election, v: Vote, last_term: u64, last_index: u64) -> bool {
    let a = advanced(s, v.term);
    v.term == a.term && (a.voted_for == None::<u64> || a.voted_for == Some(v.candidate))
        && (v.last_term > last_term || (v.last_term == last_term && v.last_index >= last_index))
}
pub open spec fn vote_result(s: Election, v: Vote, last_term: u64, last_index: u64) -> Election {
    let a = advanced(s, v.term);
    if grant(s, v, last_term, last_index) { Election { voted_for: Some(v.candidate), ..a } } else { a }
}
pub fn request_vote(s: Election, v: Vote, last_term: u64, last_index: u64) -> (r: (Election, Reply))
    ensures r.0 == vote_result(s,v,last_term,last_index),
        r.1 == (Reply { term: r.0.term, granted: grant(s,v,last_term,last_index) }),
        r.0.term >= s.term,
        s.term == r.0.term && s.voted_for.is_some() ==> r.0.voted_for == s.voted_for,
{
    let mut a = advance(s, v.term);
    let ok = v.term == a.term && (a.voted_for == None::<u64> || a.voted_for == Some(v.candidate))
        && (v.last_term > last_term || (v.last_term == last_term && v.last_index >= last_index));
    if ok { a.voted_for = Some(v.candidate); }
    (a, Reply { term: a.term, granted: ok })
}
pub open spec fn heartbeat_result(s: Election, term: u64) -> Election {
    let a = advanced(s,term);
